  uint32_t num = 0, den = 0;
  EXPECT_EQ(gimg_doc_pixel_aspect_ratio(doc, &num, &den), 1);
  EXPECT_EQ(num, 4u);
  EXPECT_EQ(den, 3u);

  // And it is not mistaken for a resolution: no density was stated.
  GIMG_Meta_Common * common = gimg_doc_meta_common(doc);
