TEST(PngMeta, TheBackgroundColourIsReadFromBKGD) {
  // bKGD (11.3.4.1) was parsed and preserved as bytes but never reported:
  // gimg_doc_background_color() existed, GIF filled it, and PNG did not.  A
  // caller asking a PNG what colour belongs behind it got "nothing stated" for
  // every file that stated one.
  //
  // What the payload means depends on the color type beside it, which is the
  // reason for three files rather than one - a reader that handled only its
  // own favourite shape would pass a single-fixture test.  The expected values
  // are ImageMagick's, which reports srgb(128,128,128), srgb(32,64,96) and
  // srgb(119,119,119) for these three.
  struct Case {
    const char * file;
    uint8_t r, g, b;
    const char * why;
  };
  const Case cases[] = {
      {"png_gray8_bkgd_sbit.png", 128, 128, 128,
          "two bytes are a gray level, and gray is R=G=B"},
      {"png_palette_trns_bkgd_hist.png", 0x20, 0x40, 0x60,
          "one byte is an index, and PLTE entry 1 is this colour"},
      {"png_gray4_trns_bkgd_sbit.png", 119, 119, 119,
          "gray 7 of 15 rescales to 119 at eight bits (13.12)"},
      {"png_rgb16_bkgd.png", 0x12, 0x56, 0x9A,
          "16-bit samples come down to eight by the same rule"},
  };
  for (const Case & c : cases) {
    std::vector<uint8_t> buf;
    ASSERT_TRUE(png_test::load_png_file(c.file, buf))
        << "Run tests/data/png/generate.py";
    GIMG_Stream * s = nullptr;
    ASSERT_EQ(gimg_stream_create_memory(buf.data(), buf.size(), &s), GIMG_OK);
    GIMG_Doc * doc = nullptr;
    ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK);

    uint8_t rgba[4] = {9, 9, 9, 9};
    EXPECT_EQ(gimg_doc_background_color(doc, rgba), 1) << c.file;
    EXPECT_EQ(rgba[0], c.r) << c.file << ": " << c.why;
    EXPECT_EQ(rgba[1], c.g) << c.file << ": " << c.why;
    EXPECT_EQ(rgba[2], c.b) << c.file << ": " << c.why;
    EXPECT_EQ(rgba[3], 255u)
        << "bKGD names a colour to put behind the image; a transparent one "
           "would say nothing";
    gimg_doc_destroy(doc);
    gimg_stream_destroy(s);
  }
}

TEST(PngMeta, ABKGDOfTheWrongLengthIsNotAColour) {
  // Three bytes where color type 0 calls for two.  The file is malformed and
  // there is no way to know which two of the three were meant, so nothing is
  // reported rather than a colour guessed from a payload that does not say
  // one.  Reading it as the first two bytes would give a plausible gray and
  // never look wrong.
  std::vector<uint8_t> buf;
  ASSERT_TRUE(png_test::load_png_file("png_gray8_bad_bkgd.png", buf))
      << "Run tests/data/png/generate.py";
  GIMG_Stream * s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory(buf.data(), buf.size(), &s), GIMG_OK);
  GIMG_Doc * doc = nullptr;
  ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK);
  uint8_t rgba[4] = {9, 9, 9, 9};
  EXPECT_EQ(gimg_doc_background_color(doc, rgba), 0);
  EXPECT_EQ(rgba[0], 9u) << "the out-param is left alone when nothing is said";
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

namespace {

/** The first error diagnostic a load produced, or "" if it produced none. */
std::string refusal_reason(
    const std::vector<uint8_t> & png, GIMG_Result * out_result) {
  GIMG_Stream * s = nullptr;
  if (gimg_stream_create_memory(png.data(), png.size(), &s) != GIMG_OK) {
    return "<no stream>";
  }
  GIMG_Diagnostics diag = {};
  GIMG_Doc * doc = nullptr;
  const GIMG_Result r = gimg_doc_load(s, nullptr, &diag, &doc);
  if (out_result) {
    *out_result = r;
  }
  std::string why;
  for (size_t i = 0; i < diag.count; i++) {
    if (diag.items[i].severity == GIMG_DIAG_ERROR &&
        diag.items[i].recommended_action) {
      why = diag.items[i].recommended_action;
      break;
    }
  }
  gimg_diagnostics_destroy(&diag);
  if (doc) {
    gimg_doc_destroy(doc);
  }
  gimg_stream_destroy(s);
  return why;
}

/** Refused, with a first error diagnostic naming @p needle. */
::testing::AssertionResult RefusedBecause(
    const std::vector<uint8_t> & png, const char * needle) {
  GIMG_Result r = GIMG_OK;
  const std::string why = refusal_reason(png, &r);
  if (r == GIMG_OK) {
    return ::testing::AssertionFailure() << "the file loaded";
  }
  if (why.empty()) {
    return ::testing::AssertionFailure()
        << "refused with " << (int)r << " and said nothing";
  }
  if (why.find(needle) == std::string::npos) {
    return ::testing::AssertionFailure()
        << "refused because \"" << why << "\", which does not mention \""
        << needle << "\"";
  }
  return ::testing::AssertionSuccess();
}

/** An IHDR with every field spelled out, for the ones ihdr() fixes at 0. */
std::vector<uint8_t> RawIhdr(uint32_t w, uint32_t h, uint8_t depth, uint8_t ct,
    uint8_t compression, uint8_t filter, uint8_t interlace) {
  return {(uint8_t)(w >> 24), (uint8_t)(w >> 16), (uint8_t)(w >> 8), (uint8_t)w,
      (uint8_t)(h >> 24), (uint8_t)(h >> 16), (uint8_t)(h >> 8), (uint8_t)h,
      depth, ct, compression, filter, interlace};
}

} // namespace

/**
 * A refused PNG says which rule it broke.
 *
 * The result code is four bits of information - GIMG_ERR_FORMAT covers an
 * IHDR with a colour type of 5, a PLTE on a grayscale image, and an fdAT
 * before any fcTL - and a caller holding a file that will not load has
 * nothing to act on. The library's own documentation tells callers to use
 * "the result code and GIMG_Diagnostics, which load and decode do fill".
 *
 * They did not. Measured over tests/fuzz/corpus, 8,403 files with a
 * recognised signature: the BMP loader explained every one of its 215
 * refusals and the GIF loader every one of its 97, while the PNG loader
 * explained 51 of 245. **194 refusals said nothing at all.** Of those, 60
 * were an IHDR the parser rejected without reporting which field, and the
 * rest were chunk-ordering and chunk-length rules whose refusal sites simply
 * did not call the diagnostic helper sitting beside them. The same run now
 * reports 11.
 *
 * Each case below breaks one rule and asserts the reason names it - not
 * merely that something was said - and each group carries a control that
 * loads, so a loader that refused everything with a plausible message could
 * not pass.
 */
TEST(PngLoad, ARefusedFileSaysWhichRuleItBroke) {
  // --- IHDR: the chunk that says what the image is.
  {
    PngBuilder b;
    b.chunk("IHDR", RawIhdr(0, 4, 8, 0, 0, 0, 0));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "no area"));
  }
  {
    PngBuilder b;
    b.chunk("IHDR", RawIhdr(4, 4, 8, 5, 0, 0, 0));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "colour type must be"));
  }
  {
    PngBuilder b;
    b.chunk("IHDR", RawIhdr(4, 4, 3, 0, 0, 0, 0));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "grayscale image is"));
  }
  {
    PngBuilder b;
    b.chunk("IHDR", RawIhdr(4, 4, 4, 2, 0, 0, 0));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "truecolour image is"));
  }
  {
    PngBuilder b;
    b.chunk("IHDR", RawIhdr(4, 4, 16, 4, 0, 0, 0));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    // 16 is legal for colour type 4, so this one is about the depth being
    // legal: the refusal must come from somewhere else or not at all.
    GIMG_Result r = GIMG_OK;
    (void)refusal_reason(b.bytes(), &r);
    EXPECT_NE(r, GIMG_ERR_FORMAT)
        << "16-bit gray+alpha is PNG Table 11.1's own combination";
  }
  {
    PngBuilder b;
    b.chunk("IHDR", RawIhdr(4, 4, 8, 0, 1, 0, 0));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "compression method"));
  }
  {
    PngBuilder b;
    b.chunk("IHDR", RawIhdr(4, 4, 8, 0, 0, 0, 2));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "interlace method"));
  }

  // --- Chunks that may not appear, or not there, or not that long.
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("PLTE", std::vector<uint8_t>(3, 0x40));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "grayscale"));
  }
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 3).chunk("PLTE", std::vector<uint8_t>(4, 0x40));
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "multiple of three"));
  }
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 6).chunk("tRNS", {0x00, 0x01});
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "already carries alpha"));
  }
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("tRNS", {0x00});
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "one 16-bit sample"));
  }
  {
    // A critical chunk nothing knows: 5.4 says a decoder must not skip one.
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("CrIt", {0x01});
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "critical chunk"));
  }

  // --- APNG.
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("acTL", {0, 0, 0, 1, 0, 0, 0});
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "acTL is eight bytes"));
  }
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("fdAT", {0, 0, 0, 1, 0x78, 0x01});
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    EXPECT_TRUE(RefusedBecause(b.bytes(), "only in an APNG"));
  }

  // --- The controls: each of these must load, and say nothing.
  struct Good {
    const char * what;
    std::vector<uint8_t> bytes;
  };
  std::vector<Good> good;
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    good.push_back({"plain grayscale", b.bytes()});
  }
  {
    PngBuilder b;
    b.ihdr(4, 4, 8, 0).chunk("tRNS", {0x00, 0x01});
    b.chunk("IDAT", GrayIdatPayload(4, 4)).chunk("IEND", {});
    good.push_back({"grayscale with a transparent value", b.bytes()});
  }
  {
    PngBuilder b;
    b.chunk("IHDR", RawIhdr(4, 4, 16, 4, 0, 0, 0));
    b.chunk("IDAT", GrayIdatPayload(16, 4)).chunk("IEND", {});
    good.push_back({"16-bit gray+alpha", b.bytes()});
  }
  for (const Good & g : good) {
    SCOPED_TRACE(g.what);
    GIMG_Result r = GIMG_OK;
    const std::string why = refusal_reason(g.bytes, &r);
    EXPECT_EQ(r, GIMG_OK) << "refused a file that breaks no rule: " << why;
    EXPECT_TRUE(why.empty()) << "a file that loaded reported an error: " << why;
  }
}

namespace {

/**
 * Porter-Duff Over, non-premultiplied, written out from the spec rather than
 * copied from the decoder - PNG's "Alpha Channel Processing", which APNG's
 * BLEND_OP_OVER points at:
 *
 *     Ao = As + Ad*(1-As)
 *     Co = (Cs*As + Cd*Ad*(1-As)) / Ao
 *
 * Integer form: with As = sa/255, Ad = da/255 and (1-As) = inv/255, both
 * sides carry 255^2 and cancel.
 */
void spec_over(const uint8_t src[4], const uint8_t dst[4], uint8_t out[4]) {
  const unsigned sa = src[3], da = dst[3];
  if (sa == 255u) {
    for (int i = 0; i < 4; i++) { out[i] = src[i]; }
    return;
  }
  if (sa == 0u) {
    for (int i = 0; i < 4; i++) { out[i] = dst[i]; }
    return;
  }
  const unsigned inv = 255u - sa;
  const unsigned ao = sa * 255u + da * inv;
  for (int i = 0; i < 3; i++) {
    out[i] = (uint8_t)(((unsigned)src[i] * sa * 255u +
                           (unsigned)dst[i] * da * inv) / ao);
  }
  out[3] = (uint8_t)(ao / 255u);
}

} // namespace

/**
 * APNG's BLEND_OP_OVER, onto a canvas that is not fully opaque.
 *
 * This was wrong, and nothing could see it: every APNG fixture that used OVER
 * was 1x1, and the only 8-bit one was grayscale - where the source alpha is
 * always 255, so the partial-alpha arm never ran on any input. The arm is the
 * whole of APNG's OVER.
 *
 * What it did was Co = (Cs*As + Cd*(1-As)), which is Porter-Duff with the
 * destination's own alpha dropped and the division by the composite alpha
 * dropped with it. That simplification is exact when the destination is
 * opaque - the sixteen-bit branch even said so in a comment - and wrong
 * everywhere else. The failure is not a rounding difference: over a fully
 * transparent destination the spec says the destination contributes nothing,
 * while the simplified form mixes in whatever colour is stored behind that
 * zero alpha. A canvas is transparent wherever no frame has painted yet, so
 * that is the ordinary case.
 *
 * The expectation is computed from the spec formula rather than taken from
 * another decoder, because the obvious oracle is wrong here too: Pillow's
 * APNG path produces this same incorrect colour, and disagrees with Pillow's
 * own Image.alpha_composite - which does match the formula below, on every
 * pixel of this fixture. An oracle that shares the bug reads as agreement.
 */
TEST(PngDecode, AFrameBlendedOverATransparentCanvasIgnoresWhatIsBehindIt) {
  std::vector<uint8_t> bytes;
  ASSERT_TRUE(
      png_test::load_png_file("png_apng_blend_over_partial.png", bytes));

  GIMG_Stream * s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory(bytes.data(), bytes.size(), &s), GIMG_OK);
  GIMG_Doc * doc = nullptr;
  ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK);
  ASSERT_EQ(gimg_doc_item_count(doc), 2u);

  // Frame 0 is written with BLEND_OP_SOURCE, so it is the canvas frame 1
  // composites onto - read it back rather than restating it here, so the
  // expectation cannot drift from the fixture.
  GIMG_Raster * first = nullptr;
  ASSERT_EQ(gimg_item_decode(gimg_doc_item(doc, 0), nullptr, &first), GIMG_OK);
  ASSERT_NE(first, nullptr);
  const uint32_t w = gimg_raster_width(first), h = gimg_raster_height(first);
  ASSERT_EQ(w, 4u);
  ASSERT_EQ(h, 2u);

  std::vector<uint8_t> canvas((size_t)w * h * 4u);
  {
    const auto * p = (const uint8_t *)gimg_raster_pixels_const(first);
    const size_t stride = gimg_raster_stride_bytes(first);
    for (uint32_t y = 0; y < h; y++) {
      memcpy(canvas.data() + (size_t)y * w * 4u, p + (size_t)y * stride, w * 4u);
    }
  }
  gimg_raster_destroy(first);

  // The second frame's own pixels, as the fixture stores them.
  const uint8_t frame[2][4][4] = {
      {{0, 0, 255, 128}, {255, 255, 255, 128}, {0, 0, 0, 64}, {0, 255, 255, 192}},
      {{255, 255, 0, 200}, {0, 0, 0, 128}, {255, 255, 255, 255}, {1, 2, 3, 0}},
  };

  GIMG_Raster * second = nullptr;
  ASSERT_EQ(gimg_item_decode(gimg_doc_item(doc, 1), nullptr, &second), GIMG_OK);
  ASSERT_NE(second, nullptr);
  const auto * got = (const uint8_t *)gimg_raster_pixels_const(second);
  const size_t got_stride = gimg_raster_stride_bytes(second);

  long transparent_destinations = 0;
  for (uint32_t y = 0; y < h; y++) {
    for (uint32_t x = 0; x < w; x++) {
      SCOPED_TRACE("pixel " + std::to_string(x) + "," + std::to_string(y));
      const uint8_t * dst = canvas.data() + ((size_t)y * w + x) * 4u;
      uint8_t want[4];
      spec_over(frame[y][x], dst, want);
      const uint8_t * have = got + (size_t)y * got_stride + (size_t)x * 4u;
      for (int c = 0; c < 4; c++) {
        EXPECT_EQ((int)have[c], (int)want[c])
            << "channel " << c << " of the composite";
      }
      if (dst[3] == 0) { transparent_destinations++; }
    }
  }
  // The alarm: the case that fails against the old code is the one where the
  // destination is invisible, so the fixture has to contain some.
  ASSERT_GT(transparent_destinations, 0)
      << "no pixel in this fixture composites over a transparent destination, "
         "so it cannot see the defect it was written for";

  gimg_raster_destroy(second);
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

/**
 * The same rule at sixteen bits, because it is a different loop.
 *
 * The decoder composites 8-bit and 16-bit frames through separate code, and
 * both carried the same simplification - the sixteen-bit one with a comment
 * spelling out the full formula directly above code that did not implement
 * it. Fixing one and testing one would have left the other exactly as it was.
 *
 * The fixture is the eight-bit one scaled by 257, so every sample is an exact
 * 16-bit representation of its 8-bit value and the two tests can be compared
 * by eye when one of them fails.
 */
TEST(PngDecode, ASixteenBitFrameBlendsTheSameWayAnEightBitOneDoes) {
  std::vector<uint8_t> bytes;
  ASSERT_TRUE(
      png_test::load_png_file("png_apng_blend_over_partial16.png", bytes));
  GIMG_Stream * s = nullptr;
  ASSERT_EQ(gimg_stream_create_memory(bytes.data(), bytes.size(), &s), GIMG_OK);
  GIMG_Doc * doc = nullptr;
  ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK);
  ASSERT_EQ(gimg_doc_item_count(doc), 2u);

  GIMG_Raster * first = nullptr;
  ASSERT_EQ(gimg_item_decode(gimg_doc_item(doc, 0), nullptr, &first), GIMG_OK);
  ASSERT_NE(first, nullptr);
  ASSERT_EQ(gimg_raster_format(first)->bits_per_channel[0], 16);
  const uint32_t w = gimg_raster_width(first), h = gimg_raster_height(first);

  std::vector<uint16_t> canvas((size_t)w * h * 4u);
  {
    const auto * p = (const uint8_t *)gimg_raster_pixels_const(first);
    const size_t stride = gimg_raster_stride_bytes(first);
    for (uint32_t y = 0; y < h; y++) {
      memcpy(canvas.data() + (size_t)y * w * 4u, p + (size_t)y * stride,
          (size_t)w * 8u);
    }
  }
  gimg_raster_destroy(first);

  const uint8_t frame8[2][4][4] = {
      {{0, 0, 255, 128}, {255, 255, 255, 128}, {0, 0, 0, 64}, {0, 255, 255, 192}},
      {{255, 255, 0, 200}, {0, 0, 0, 128}, {255, 255, 255, 255}, {1, 2, 3, 0}},
  };

  GIMG_Raster * second = nullptr;
  ASSERT_EQ(gimg_item_decode(gimg_doc_item(doc, 1), nullptr, &second), GIMG_OK);
  ASSERT_NE(second, nullptr);
  const auto * got = (const uint8_t *)gimg_raster_pixels_const(second);
  const size_t got_stride = gimg_raster_stride_bytes(second);

  long transparent_destinations = 0;
  for (uint32_t y = 0; y < h; y++) {
    for (uint32_t x = 0; x < w; x++) {
      SCOPED_TRACE("pixel " + std::to_string(x) + "," + std::to_string(y));
      const uint16_t * dst = canvas.data() + ((size_t)y * w + x) * 4u;
      const uint64_t sa = (uint64_t)frame8[y][x][3] * 257u;
      const uint64_t da = dst[3];
      uint16_t want[4];
      if (sa == 65535u) {
        for (int c = 0; c < 4; c++) {
          want[c] = (uint16_t)(frame8[y][x][c] * 257u);
        }
      }
      else if (sa == 0u) {
        for (int c = 0; c < 4; c++) { want[c] = dst[c]; }
      }
      else {
        const uint64_t inv = 65535u - sa;
        const uint64_t ao = sa * 65535u + da * inv;
        for (int c = 0; c < 3; c++) {
          want[c] = (uint16_t)(((uint64_t)frame8[y][x][c] * 257u * sa * 65535u +
                                   (uint64_t)dst[c] * da * inv) / ao);
        }
        want[3] = (uint16_t)(ao / 65535u);
      }
      const auto * have =
          (const uint16_t *)(const void *)(got + (size_t)y * got_stride +
              (size_t)x * 8u);
      for (int c = 0; c < 4; c++) {
        EXPECT_EQ((int)have[c], (int)want[c]) << "channel " << c;
      }
      if (dst[3] == 0) { transparent_destinations++; }
    }
  }
  ASSERT_GT(transparent_destinations, 0);

  gimg_raster_destroy(second);
  gimg_doc_destroy(doc);
  gimg_stream_destroy(s);
}

/**
 * The colour type an APNG is stored in must not change the picture it makes.
 *
 * The canvas an APNG composites into is chosen by colour type, and every APNG
 * fixture was type 0 or 6 - so the arms for truecolour, palette and
 * gray+alpha had never run, in a decoder where the frame also has to be
 * expanded to RGBA (a tRNS key for type 2, per-entry alpha for type 3,
 * replicated gray for type 4) before it can be blended at all.
 *
 * Each fixture is paired with an RGBA8 file holding the same picture already
 * expanded, so this is a differential rather than a table of expected pixels:
 * whatever the right answer is, both files must give it. That needs no
 * hand-written expectation - which would be a second chance to encode the
 * same misunderstanding - and no outside decoder, which on this format has
 * already been shown to share our mistakes.
 */
TEST(PngDecode, AnApngsColorTypeDoesNotChangeThePictureItComposites) {
  const struct {
    const char * typed;
    const char * rgba;
    const char * what;
  } cases[] = {
      {"png_apng_ct2_trns.png", "png_apng_ct2_trns_rgba.png",
          "truecolour with a tRNS key"},
      {"png_apng_ct3_trns.png", "png_apng_ct3_trns_rgba.png",
          "palette with per-entry alpha"},
      {"png_apng_ct4.png", "png_apng_ct4_rgba.png", "gray plus alpha"},
  };

  for (const auto & c : cases) {
    SCOPED_TRACE(c.what);
    std::vector<uint8_t> frames[2][2]; // [file][frame index]
    const char * names[2] = {c.typed, c.rgba};
    for (int f = 0; f < 2; f++) {
      std::vector<uint8_t> bytes;
      ASSERT_TRUE(png_test::load_png_file(names[f], bytes)) << names[f];
      GIMG_Stream * s = nullptr;
      ASSERT_EQ(
          gimg_stream_create_memory(bytes.data(), bytes.size(), &s), GIMG_OK);
      GIMG_Doc * doc = nullptr;
      ASSERT_EQ(gimg_doc_load(s, nullptr, nullptr, &doc), GIMG_OK) << names[f];
      ASSERT_EQ(gimg_doc_item_count(doc), 2u) << names[f];
      for (size_t i = 0; i < 2; i++) {
        GIMG_Raster * r = nullptr;
        ASSERT_EQ(gimg_item_decode(gimg_doc_item(doc, i), nullptr, &r),
            GIMG_OK);
        ASSERT_NE(r, nullptr);
        const GIMG_Pixel_Format * fmt = gimg_raster_format(r);
        // Both sides decode to a composited RGBA8 canvas; if that ever stops
        // being true the comparison below would be meaningless.
        ASSERT_EQ(fmt->channel_count, 4);
        ASSERT_EQ(fmt->bits_per_channel[0], 8);
        const uint32_t w = gimg_raster_width(r), h = gimg_raster_height(r);
        const size_t stride = gimg_raster_stride_bytes(r);
        const auto * p = (const uint8_t *)gimg_raster_pixels_const(r);
        frames[f][i].resize((size_t)w * h * 4u);
        for (uint32_t y = 0; y < h; y++) {
          memcpy(frames[f][i].data() + (size_t)y * w * 4u,
              p + (size_t)y * stride, (size_t)w * 4u);
        }
        gimg_raster_destroy(r);
      }
      gimg_doc_destroy(doc);
      gimg_stream_destroy(s);
    }
    ASSERT_FALSE(frames[0][0].empty());
    EXPECT_EQ(frames[0][0], frames[1][0])
        << "the first frame already differs, so the expansion to RGBA is "
           "wrong before any compositing happens";
    EXPECT_EQ(frames[0][1], frames[1][1])
        << "the frames expand the same way but composite differently";
  }
}
